void setup() {
  // Set all pins on Port B (Pins 8 to 13) as OUTPUT
  // B00100000 sets Pin 13 (Bit 5) as OUTPUT
  DDRB = 0B00100000; 
}

void loop() {
  // Set Pin 13 HIGH safely using a bitwise OR (|) and bit shifting (<<)
PORTB |= (1 << 5); 
delay(1000);
// Set Pin 13 LOW safely using a bitwise AND (&) and a bitwise NOT (~)
PORTB &= ~(1 << 5); 
delay(1000);
}
